insert into woerter (slug, wort, artikel, ipa, wortart, kategorie, definition, bedeutungen, beispiel) values
  ('des-is-ned-mea-ois-a-schaas-mit-quastln', 'Des is ned mea ois a Schaas mit Quastln!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Das ist nicht mehr als ein Schas mit Quasteln!', '[{"kategorie": "wörtlich", "text": "\"Das ist nicht mehr als ein Scheißdreck mit Mascherl!\"  2. \"Das ist nichts als heiße Luft mit Deko!\"  3. (Deutschland): \"Das ist nicht mehr als Quatsch mit Soße!\""}]'::jsonb, 'a Schaas mit Quastln'),
  ('des-is-ned-mea-ois-a-schaas-mit-tupfn', 'Des is ned mea ois a Schaas mit Tupfn!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Das ist nicht mehr als ein Schas mit Tupfen!', '[{"kategorie": "wörtlich", "text": "\"Das ist nicht mehr als ein Furz mit Farbklecksen!\"  2. Das ist nicht mehr als ein Scheißdreck mit Mascherl!  3. (Deutschland): Das ist nicht mehr als Quatsch mit Soße!"}]'::jsonb, 'a Schaas mit Tupfn'),
  ('bist-schaasaugat', 'Bist schaasaugat?', '', '', '', 'Wiener Sprüche, die sitzen!', 'Bist du schasaugert?', '[{"kategorie": "wörtlich", "text": "\"Bist du blind?\"  2. \"Siehst du schlecht oder was?\"  3. \"Hast du Tomaten auf den Augen?\""}]'::jsonb, ''),
  ('a-schaas-im-woid', 'a Schaas im Woid', '', '', '', 'Echte Wiener Schmähperlen', 'ein Schas im Wald', '[{"kategorie": "wörtlich", "text": "\"ein Furz im Walde\""}, {"kategorie": "scherzhaft für", "text": "\"ein Lüfterl im Nirgendwo\""}, {"kategorie": "", "text": "\"ein Windhauch im Nichts\""}, {"kategorie": "", "text": "\"ein Pfiff im Wald\""}]'::jsonb, ''),
  ('wiara-schaas-im-woid', 'wiara Schaas im Woid', '', '', '', 'Wiener Sprüche, die sitzen!', 'wie ein Schas im Wald', '[{"kategorie": "wörtlich", "text": "\"wie ein Furz im Walde\""}, {"kategorie": "fig.", "text": "\"wie ein Pfiff im Wald\""}, {"kategorie": "", "text": "\"wie ein Lüfterl im Nirgendwo\""}, {"kategorie": "", "text": "\"wie ein Windhauch im Nichts\""}]'::jsonb, 'Kaa Seawas, kaa Babaa - aafoch weg wiara Schaas im Woid!'),
  ('kaa-seawas-kaa-babaa-aafoch-weg-wiara-schaas-im-woid', 'Kaa Seawas, kaa Babaa - aafoch weg wiara Schaas im Woid!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Kein Servus, kein Baba – einfach weg wie ein Schas im Wald!', '[{"kategorie": "wörtlich", "text": "\"Kein Servus, kein Baba - einfach weg wie ein Pfiff im Wald!\"  2. \"Kein Abschied, kein Pfiat-di - einfach weg wie ein Lüfterl im Nirgendwo!\"  3. \"Ohne Tschüss, ohne Erklärung – plötzlich verschwunden wie ein Windhauch im Nichts!\""}]'::jsonb, 'a Schaas im Woid'),
  ('vakumma-wiara-schaas-im-woid', 'vakumma wiara Schaas im Woid', '', '', '', 'Wiener Sprüche, die sitzen!', 'verkommen wie ein Schas im Wald', '[{"kategorie": "wörtlich", "text": "\"verkommen wie ein Furz im Walde\""}, {"kategorie": "fig.", "text": "\"im Nichts verpuffen\""}, {"kategorie": "", "text": "\"im Sand verlaufen\""}, {"kategorie": "", "text": "\"sich wie ein Furz in Luft auflösen\""}, {"kategorie": "", "text": "[[verhungern wie ein Schas im Wald]]"}]'::jsonb, 'De gaunze Aufreegung is aum End vakumma wiara Schaas im Woid!'),
  ('de-gaunze-aufreegung-is-aum-end-vakumma-wiara-schaas-im-woid', 'De gaunze Aufreegung is aum End vakumma wiara Schaas im Woid!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Die ganze Aufregung ist am Ende verkommen wie ein Schas im Wald!', '[{"kategorie": "wörtlich", "text": "\"Die ganze Aufregung ist am Ende im Nichts verpufft!\"  2. \"Die ganze Aufregung ist am Ende im Sande verlaufen!\"  3. \"Am Schluss ist von der ganzen Aufregung nichts übrig geblieben!\""}]'::jsonb, 'vakumma wiara Schaas im Woid'),
  ('vaschwindn-wiara-schaas-im-woid', 'vaschwindn wiara Schaas im Woid', '', '', '', 'Wiener Sprüche, die sitzen!', 'verschwinden wie ein Schas im Wald', '[{"kategorie": "wörtlich", "text": "\"verschwinden wie ein Furz im Walde\""}, {"kategorie": "fig.", "text": "\"sich wie ein Furz in Luft auflösen\""}, {"kategorie": "", "text": "\"sang- und klanglos verschwinden\""}, {"kategorie": "", "text": "\"leise und unbemerkt abdampfen\""}, {"kategorie": "", "text": "\"sich dezent aus dem Staub machen\""}, {"kategorie": "", "text": "\"einfach abkacken und weg sein\""}]'::jsonb, 'Grooss reedn, nix liifan - und daunn vaschwindn wiara Schaas im Woid!'),
  ('grooss-reedn-nix-liifan-und-daunn-vaschwindn-wiara-schaas-im-woid', 'Grooss reedn, nix liifan - und daunn vaschwindn wiara Schaas im Woid!', '', '', '', 'Wiener Gaunersprache', 'Groß reden, nichts liefern - und dann verschwinden wie ein Schas im Wald!', '[{"kategorie": "wörtlich", "text": "\"Groß reden, nichts liefern - und dann verschwinden wie ein Pfiff im Wald!\"  2. \"Viel ankündigen, nichts leisten - und dann sang- und klanglos abhauen!\"  3. \"Große Worte, keine Taten – und dann einfach abkacken und weg sein!\""}]'::jsonb, 'vaschwindn wiara Schaas im Woid'),
  ('vaschwindn-wiara-schaas-aus-da-latean', 'vaschwindn wiara Schaas aus da Latean', '', '', '', 'Wiener Sprüche, die sitzen!', 'verschwinden wie ein Schas aus der Laterne', '[{"kategorie": "wörtlich", "text": "\"verschwinden wie ein Furz aus der Laterne\""}, {"kategorie": "scherzhaft für", "text": "\"sich leise und unbemerkt aus dem Rampenlicht stehlen\""}, {"kategorie": "", "text": "\"sich unbemerkt in Luft auflösen\""}, {"kategorie": "", "text": "\"sich leise aus dem Staub machen\""}, {"kategorie": "", "text": "\"sich still und leise von der Bühne stehlen\""}, {"kategorie": "", "text": "\"einfach abkacken und weg sein\""}]'::jsonb, 'A kuaza Auftritt, daunn woara weg - vaschwundn wiara Schaas aus da Latean!'),
  ('a-kuaza-auftritt-daunn-woara-weg-vaschwundn-wiara-schaas-aus-da-latean', 'A kuaza Auftritt, daunn woara weg - vaschwundn wiara Schaas aus da Latean!', '', '', '', 'Handwerk und Beruf – so sagt''s der Wiener!', 'Ein kurzer Auftritt, dann war er weg – verschwunden wie ein Schas aus der Latern''!', '[{"kategorie": "wörtlich", "text": "\"Ein kurzer Auftritt, dann war er verschwunden – einfach abgekackt und weg!\"  2. \"Kurz auf der Bühne und dann weg - still und leise abgetaucht wie ein Lüftchen ins Nichts!\"  3. \"Kurz im Rampenlicht und dann weg - sang- und klanglos verschwunden wie ein Pfiff im Wald!\""}]'::jsonb, 'vaschwindn wiara Schaas aus da Latean'),
  ('vahungan-wiara-schaas-im-woid', 'vahungan wiara Schaas im Woid', '', '', '', 'Wiener Sprüche, die sitzen!', 'verhungern wie ein Schas im Wald', '[{"kategorie": "wörtlich", "text": "\"verhungern wie ein Furz im Walde\""}, {"kategorie": "fig.", "text": "\"im Nichts verpuffen\""}, {"kategorie": "", "text": "\"verhallen wie ein Seufzer im Wald\""}, {"kategorie": "", "text": "\"sang- und klanglos versanden\""}, {"kategorie": "", "text": "[[verkommen wie ein Schas im Wald]]"}]'::jsonb, 'Vüü Heazbluad, weenich Publikum - da Applaus is vahungad wiara Schaas im Woid!'),
  ('vueue-heazbluad-weenich-publikum-da-applaus-is-vahungad-wiara-schaas-im-woid', 'Vüü Heazbluad, weenich Publikum - da Applaus is vahungad wiara Schaas im Woid!', '', '', '', 'Wienerisches aus Musik, Kunst, Kultur & Medien', 'Viel Herzblut, wenig Publikum - der Applaus ist verhungert wie ein Schas im Wald!', '[{"kategorie": "wörtlich", "text": "\"Viel Einsatz, null Echo – der Applaus ist verebbt wie ein Pfiff im Wald!\"  2. \"Viel Leidenschaft, wenig Resonanz – der Beifall ist verstummt wie ein Flüstern im Wald!\"  3. \"Viel Hingabe, wenig Aufmerksamkeit – der Beifall ist verhallt wie ein Seufzer im Wald!\""}]'::jsonb, 'vahungan wiara Schaas im Woid'),
  ('schaas-schbueuen', 'Schaas schbüün', '', '', '', 'Echte Wiener Schmähperlen', 'Schas spielen', '[{"kategorie": "wörtlich", "text": "\"Furz spielen\""}, {"kategorie": "scherzhaft für", "text": "\"sich wie ein Furz in Luft auflösen\""}, {"kategorie": "", "text": "\"sich still und leise davonstehlen\""}, {"kategorie": "", "text": "\"sang- und klanglos verschwinden\""}]'::jsonb, 'Schbüü Schaas und vaziag di!'),
  ('schbueue-schaas-und-vaziag-di', 'Schbüü Schaas und vaziag di!', '', '', '', 'Schimpfen und Fluchen auf Wienerisch', 'Spiel'' Schas und verzieh'' dich!', '[{"kategorie": "wörtlich", "text": "\"Tu so, als wärst du ein Furz, und verzieh dich!\""}, {"kategorie": "", "text": "Mach''s wie ein Furz und verzieh dich!  3. Hau ab und lös dich in Luft auf!"}]'::jsonb, 'Schaas schbüün'),
  ('weng-an-jeedn-schaas-grantich-wean', 'weng an jeedn Schaas grantich wean', '', '', '', 'Wiener Sprüche, die sitzen!', 'wegen jedem Schas grantig werden', '[{"kategorie": "wörtlich", "text": "\"wegen jedem Furz sauer werden\""}, {"kategorie": "", "text": "\"sich wegen jedem Scheiß aufregen\""}, {"kategorie": "", "text": "\"wegen jeder Kleinigkeit herummeckern\""}, {"kategorie": "", "text": "\"sich über jeden Pups echauffieren\""}]'::jsonb, 'Dea wiad weng an jeedn Schaas glei grantich - aa waunn I nua in Mund aufmoch!'),
  ('dea-wiad-weng-an-jeedn-schaas-glei-grantich-aa-waunn-i-nua-in-mund-aufmoch', 'Dea wiad weng an jeedn Schaas glei grantich - aa waunn I nua in Mund aufmoch!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Der wird wegen jedem Schas gleich grantig – auch wenn ich nur den Mund aufmache!', '[{"kategorie": "wörtlich", "text": "\"Der Typ ist wegen jeder Kleinigkeit sofort sauer – selbst wenn ich nur etwas Harmloses sage!\"  2. \"Der reagiert wegen jeder Kleinigkeit gereizt - sobald ich auch nur den Mund öffne!\"  3. \"Der Kerl ist wegen jeder Lappalie gleich angepisst - ich sag ein Wort, und das genügt schon!\""}]'::jsonb, 'weng an jeedn Schaas grantich wean'),
  ('weng-an-jeedn-schaas-in-da-haeae-sei', 'weng an jeedn Schaas in da Hää sei', '', '', '', 'Wiener Sprüche, die sitzen!', 'wegen jedem Schas in der Höhe sein', '[{"kategorie": "wörtlich", "text": "\"wegen jedem Furz in der Höhe sein\""}, {"kategorie": "", "text": "\"wegen der kleinsten Kleinigkeit hochgehen\""}, {"kategorie": "", "text": "\"wegen jeder Lappalie explodieren\""}, {"kategorie": "", "text": "\"wegen jedem [[Lercherlschas]] auszucken\""}]'::jsonb, 'Dea is weng an jeedn Schaas glei i da Hää - und wundad si daunn, warum kaana mea mit eam reed!'),
  ('dea-is-weng-an-jeedn-schaas-glei-i-da-haeae-und-wundad-si-daunn-warum-kaana-mea-mit-eam-reed', 'Dea is weng an jeedn Schaas glei i da Hää - und wundad si daunn, warum kaana mea mit eam reed!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Der ist wegen jedem Furz gleich in der Höh'' – und wundert sich dann, warum keiner mehr mit ihm redet!', '[{"kategorie": "wörtlich", "text": "\"Der geht wegen jedem Furz gleich hoch – und wundert sich dann, warum keiner mehr mit ihm spricht!\"  2. \"Bei jeder Kleinigkeit geht er gleich in die Luft – und versteht nicht, warum dann keiner mehr Lust auf ihn hat!\"  3. \"Wegen jedem Scheiß rastet er aus – und wundert sich danach über Funkstille!\""}]'::jsonb, 'weng an jeedn Schaas in da Hää sei'),
  ('umanaundschiassn-wiara-schaas-in-da-hoosn', 'umanaundschiassn wiara Schaas in da Hoosn', '', '', '', 'Echte Wiener Schmähperlen', 'herumschießen wie ein Schas in der Hose', '[{"kategorie": "wörtlich", "text": "\"rumschießen wie ein Furz in der Hose\""}, {"kategorie": "scherzhaft für", "text": "\"wie ein aufgescheuchtes Huhn herumrennen\""}, {"kategorie": "", "text": "\"wie ein Furz im Wind umherirren\""}, {"kategorie": "", "text": "\"wie ein kopfloses Huhn durch die Gegend hetzen\""}, {"kategorie": "", "text": "\"unnötige Hektik verbreiten\""}]'::jsonb, 'Dea schiassd im Büro umanaund wiara Schaas in da Hoosn - vüü Hektik, nui Plan!'),
  ('dea-schiassd-im-buero-umanaund-wiara-schaas-in-da-hoosn-vueue-hektik-nui-plan', 'Dea schiassd im Büro umanaund wiara Schaas in da Hoosn - vüü Hektik, nui Plan!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Der schießt im Büro herum wie ein Schas in der Hose – viel Hektik, null Plan!', '[{"kategorie": "wörtlich", "text": "\"Er rennt im Büro herum wie ein kopfloses Huhn – viel Bewegung, null Plan!\"  2. \"Er wirkt im Büro wie ein aufgedrehter Flummi – viel Hektik, null Hirn!\"  3. \"Er irrt im Büro herum wie ein Furz im Wind - permanent in Bewegung, aber geistig im Leerlauf!\""}]'::jsonb, 'umanaundschiassn wiara Schaas in da Hoosn'),
  ('umadumschiassn-wiara-schaas-in-da-reitan', 'umadumschiassn wiara Schaas in da Reitan', '', '', '', 'Wiener Sprüche, die sitzen!', 'herumschießen wie ein Schas in der Reitern', '[{"kategorie": "wörtlich", "text": "\"herumschießen wie ein Furz am Gitterrost\""}, {"kategorie": "scherzhaft für", "text": "\"wie ein aufgescheuchtes Huhn herumrennen\""}, {"kategorie": "", "text": "\"wie ein Furz im Wind umherirren\""}, {"kategorie": "", "text": "\"wie ein kopfloses Huhn durch die Gegend hetzen\""}, {"kategorie": "", "text": "\"unnötige Hektik verbreiten\""}]'::jsonb, 'Unsa Schääf schiassd umadum wiara Schaas in da Reitan - mochd an Wiawä fia hundad, bringd owa nix weida!'),
  ('unsa-schaeaef-schiassd-umadum-wiara-schaas-in-da-reitan-mochd-an-wiawae-fia-hundad-bringd-owa-nix-weida', 'Unsa Schääf schiassd umadum wiara Schaas in da Reitan - mochd an Wiawä fia hundad, bringd owa nix weida!', '', '', '', 'Handwerk und Beruf – so sagt''s der Wiener!', 'Unser Chef schießt herum wie ein Schas in der Reitern - macht ''nen Wibel für hundert, bringt aber nichts weiter!', '[{"kategorie": "wörtlich", "text": "\"Unser Chef schießt herum wie ein Furz am Gitterrost - macht Krach wie hundert Leute, bringt aber nichts zustande!\"  2. \"Unser Chef irrt im Büro herum wie ein Furz im Wind - macht viel Lärm, ist aber komplett planlos!\"  3. \"Unser Chef hetzt im Büro herum wie ein aufgescheuchtes Huhn - permanent in Bewegung, aber geistig im Leerlauf!\""}]'::jsonb, 'umadumschiassn wiara Schaas in da Reitan'),
  ('umanaundhiasln-wiara-schaas-in-da-hoosn', 'umanaundhiasln wiara Schaas in da Hoosn', '', '', '', 'Wiener Sprüche, die sitzen!', 'rumhiaseln wie ein Schas in der Hose', '[{"kategorie": "wörtlich", "text": "\"herumschießen wie ein Furz in der Hose\""}, {"kategorie": "scherzhaft für", "text": "\"wie ein aufgescheuchtes Huhn herumrennen\""}, {"kategorie": "", "text": "\"wie ein Furz im Wind umherirren\""}, {"kategorie": "", "text": "\"wie ein kopfloses Huhn durch die Gegend hetzen\""}, {"kategorie": "", "text": "\"unnötige Hektik verbreiten\""}]'::jsonb, 'Dea hiasld umanaund wiara Schaas in da Hoosn - vüü Läam, nui Eagebnis!'),
  ('dea-hiasld-umanaund-wiara-schaas-in-da-hoosn-vueue-laeam-nui-eagebnis', 'Dea hiasld umanaund wiara Schaas in da Hoosn - vüü Läam, nui Eagebnis!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Der hetzt herum wie ein Schas in der Hose - viel Lärm, null Ergebnis!', '[{"kategorie": "wörtlich", "text": "\"Der rennt herum wie ein aufgescheuchtes Huhn - viel Lärm, null Ergenis!\"  2. \"Er hetzt herum wie ein aufgedrehter Flummi – viel Hektik, null Hirn!\"  3. \"Er irrt im Büro herum wie ein Furz im Wind - permanent in Bewegung, aber geistig im Leerlauf!\""}]'::jsonb, ''),
  ('i-bin-in-gaunz-toog-umanaundgschuald-owa-erreichd-hob-i-nix', 'I bin in gaunz Toog umanaundgschuald - owa erreichd hob I nix!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Ich bin den ganzen Tag herumgeschurlt - aber erreicht habe ich nichts!', '[{"kategorie": "wörtlich", "text": "\"Ich bin den ganzen Tag herumgehetzt - aber erreicht habe ich nichts!\"  2. \"Ich bin den ganzen Tag hin- und hergelaufen, aber ohne Ergebnis!\"  3. \"Ich bin den ganzen Tag nur herumgerannt und hab trotzdem nichts geschafft!\""}]'::jsonb, ''),
  ('wiaras-blauliachd-gseeng-hod-is-a-davooghiasld-wiara-aufgscheichds-hendl', 'Wiaras Blauliachd gseeng hod, is a davooghiasld wiara aufgscheichds Hendl!', '', '', '', 'Wiener Gaunersprache', 'Wie er das Blaulicht gesehen hat, ist er davongehiaselt wie ein aufgescheuchtes Hendl!', '[{"kategorie": "wörtlich", "text": "\"Als er das Blaulicht sah, ist er davongerannt wie ein aufgescheuchtes Huhn!\"  2. \"Kaum hat er das Blaulicht gesehen, hat er die Beine in die Hand genommen und ist fluchtartig verschwunden!\"  3. \"Kaum ist das Blaulicht angegangen, hat er die Nerven weggeschmissen und ist davongestürmt!\""}]'::jsonb, ''),
  ('wiara-sei-ex-gseeng-hod-isa-davoogschuald-wi-da-teifae-vuam-weiwossa', 'Wiara sei Ex gseeng hod, isa davoogschuald wi da Teifä vuam Weiwossa!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Wie er seine Ex gesehen hat, ist er davongeschurlt wie der Teufel vorm Weihwasser!', '[{"kategorie": "wörtlich", "text": "\"Als er seine Ex sah, ist er davongerannt wie der Teufel vor''m Weihwasser!\"  2. \"Kaum hatte er seine Ex erblickt, machte er sich blitzschnell aus dem Staub!\"  3. \"In dem Moment, als er seine Ex entdeckte, ergriff er panisch die Flucht!\""}]'::jsonb, ''),
  ('mia-san-in-beag-auffeghiasld-dass-uns-es-beischl-brennd-hod', 'Mia san in Beag auffeghiasld, dass uns es Beischl brennd hod!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Wir sind den Berg raufgehiaselt, dass uns das Beuschl gebrannt hat!', '[{"kategorie": "wörtlich", "text": "\"Wir sind den Berg raufgehetzt, dass uns die Lunge brannte!\"  2. \"Wir jagten den Berg hinauf, bis uns die Lungen brannten!\"  3. \"Wir stürmten den Hang hinauf, die Brust wie in Flammen!\""}]'::jsonb, ''),
  ('mia-san-in-beag-auffegschuald-dass-uns-es-beischl-brennd-hod', 'Mia san in Beag auffegschuald, dass uns es Beischl brennd hod!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Wir sind den Berg raufgeschurlt, dass uns das Beuschl gebrannt hat!', '[{"kategorie": "wörtlich", "text": "\"Wir sind den Berg raufgerannt, dass uns die Lunge brannte!\"  2. \"Wir jagten den Berg hinauf, bis uns die Lungen brannten!\"  3. \"Wir hetzten den Hang hinauf, die Brust wie in Flammen!\""}]'::jsonb, ''),
  ('dea-is-de-gossn-owegschuald-kumma-ois-daed-eam-da-oasch-auf-grundeis-gee', 'Dea is de Gossn owegschuald kumma, ois däd eam da Oasch auf Grundeis gee!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Der ist die Gasse runtergeschurlt gekommen, als täte ihm der Arsch auf Grundeis gehen!', '[{"kategorie": "wörtlich", "text": "\"Der kam die Gasse runtergejagt, als würde ihm der Arsch auf Grundeis gehen!\"  2. \"Der kam die Gasse heruntergerannt, als wäre der Teufel hinter ihm her!\"  3. \"Der stürzte die Gasse hinunter, als hätte er den Leibhaftigen im Nacken!\""}]'::jsonb, ''),
  ('owehiasln1', 'owehiasln1', '', '', '', 'Grundwortschatz Wienerisch', 'owehiaseln', '[{"kategorie": "wörtlich", "text": "\"hinunterhetzen\" (Kompositum aus dem abtrennbaren Präfix [[owe]]=\"hinunter\" und [[hiasln]]=\"hetzen\" [leitet sich vom männlichen Vornamen [[Hiasl]] (Matthias) ab und bezeichnet das ungeschickte, nervöse Herumhetzen einer stereotypen Figur [\"Hiasl\"=typisierend für \"einfältiger Mensch\"])"}, {"kategorie": "allg.", "text": "\"hinabhetzen\", \"hinabeilen\", \"hinabjagen\", \"hinunterstürmen\", \"hastig nach unten laufen\""}]'::jsonb, 'Dea is de Gossn oweghiasld kumma, wia waunn da Teifä hinta eam hea waarad!'),
  ('dea-is-de-gossn-oweghiasld-kumma-wia-waunn-da-teifae-hinta-eam-hea-waarad', 'Dea is de Gossn oweghiasld kumma, wia waunn da Teifä hinta eam hea waarad!', '', '', '', 'Wiener Gaunersprache', 'Der ist die Gasse runtergehiaselt gekommen, wie wenn der Teufel hinter ihm her wäre!', '[{"kategorie": "wörtlich", "text": "\"Der kam die Gasse runtergejagt, als ob der Teufel hinter ihm her wäre!\"  2. \"Der stürmte kopflos die Gasse runter, als ginge es um sein Leben!\"  3. \"Der stürzte die Gasse hinunter, als hätte er den Leibhaftigen im Nacken!\""}]'::jsonb, ''),
  ('owehiasln2', 'owehiasln2', '', '', '', 'Grundwortschatz Wienerisch', 'owehiaseln', '[{"kategorie": "wörtlich", "text": "\"runterschmieren\" (Kompositum aus dem abtrennbaren Präfix [[owe]]=\"hinunter\" und [[hiasln]]=\"schmieren\" [leitet sich vom rotwelschen \"hiesel\" ab =\"schwarzer Schmierstoff\" [\"Tarnschminke\", mit der man sich als Gauner beim Einbruch bestmöglich zu camouflieren versuchte])"}, {"kategorie": "allg.", "text": "hinschmieren, hinrotzen, \"hastig und schlampig runterkritzeln\", \"runterfetzen\""}]'::jsonb, 'I hob schnöö wos oweghiasld - bessa ois nix!'),
  ('i-hob-schnoeoe-wos-oweghiasld-bessa-ois-nix', 'I hob schnöö wos oweghiasld - bessa ois nix!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Ich hab schnell was runtergehiaselt - besser als nichts!', '[{"kategorie": "wörtlich", "text": "\"Ich hab nur hastig was runtergekritzelt - besser als nichts!\"  2. \"Ich hab nur schnell was hingeschmiert – aber besser als gar nichts!\"  3. \"Ich hab nur kurz mal was hingerotzt - besser als nichts!\""}]'::jsonb, ''),
