  ('den-haums-noch-da-festnaum-glei-ooghiasld', 'Den haums noch da Festnaum glei ooghiasld!', '', '', '', 'Wiener Gaunersprache', 'Den haben sie nach der Festnahme gleich abgehiaselt!', '[{"kategorie": "wörtlich, Gaunerjargon", "text": "\"Den haben sie sofort nach der Festnahme abgeknipst!\"  2. \"Den haben sie gleich nach der Festnahme für die Verbrecherkartei abfotografiert!\"  3. \"Unmittelbar nach der Festnahme hat ihn die Polizei auch gleich erkennungsdienstlich behandelt!\""}]'::jsonb, ''),
  ('dea-hod-de-waund-aughiasld-wiara-hiantooda-min-pinsl-im-oasch', 'Dea hod de Waund aughiasld wiara Hiantooda min Pinsl im Oasch!', '', '', '', 'Handwerk und Beruf – so sagt''s der Wiener!', 'Der hat die Wand angehiaselt wie ein Hirntoter mit''m Pinsel im Arsch!', '[{"kategorie": "wörtlich", "text": "\"Der hat die Wand angestrichen wie ein Besoffener im Delirium!\"  2. \"Der hat die Wand ausgemalt, als wär ihm das Hirn komplett abgeraucht!\"  3. \"Der hat die Wand bearbeitet, als hätte er den Farbpinsel mit''m Arsch geführt!\""}]'::jsonb, ''),
  ('tua-mi-ned-auhiasln', 'Tua mi ned auhiasln!', '', '', '', 'Krank & kuriert auf Wienerisch', 'Tu mich nicht anhiaseln!', '[{"kategorie": "wörtlich", "text": "\"Tu mich nicht anstecken!\"  2. \"Schleuder deine Bazillen woanders hin!\" 3. \"Hust woanders hin!\"  4. \"Nies mich nicht an!\""}]'::jsonb, ''),
