  ('a-scheifal-nochleeng', 'a Scheifal nochleeng', '', '', '', 'Wiener Sprüche, die sitzen!', 'ein Schäuferl nachlegen', '[{"kategorie": "wörtlich", "text": "\"ein Schäufelchen nachlegen\""}, {"kategorie": "", "text": "\"einen Zahn zulegen\""}, {"kategorie": "", "text": "\"noch eins draufsetzen\""}, {"kategorie": "", "text": "\"a Schippal noochleeng\""}, {"kategorie": "", "text": "[[a Scheitl noochleeng]]"}]'::jsonb, ''),
  ('schdott-dassa-de-goschn-hoid-leegd-dea-trottl-aa-noo-a-scheifal-nooch', 'Schdott dassa de Goschn hoid, leegd dea Trottl aa noo a Scheifal nooch!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Statt dass er die Gosch''n hält, legt der Trottel auch noch ein Schäuferl nach!', '[{"kategorie": "wörtlich", "text": "\"Statt den Mund zu halten, setzt der Idiot auch noch einen drauf!\"  2. \"Statt das Maul zu halten, gießt der Vollpfosten doch tatsächlich noch mehr Öl ins Feuer!\"  3. \"Anstatt endlich die Klappe zu halten, tritt der Trottel verbal nochmal nach!\""}]'::jsonb, 'a Scheifal nochleeng'),
  ('leeg-a-scheifal-nooch', 'Leeg a Scheifal nooch!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Leg ein Schäuferl nach!', '[{"kategorie": "wörtlich", "text": "\"Leg einen Zahn zu!\"  2. \"Leg dich noch mehr ins Zeug!\"  3. \"Leg noch einen drauf!\"  4. \"Leeg a Schippal nooch!\""}]'::jsonb, ''),
